export type TestProofBoundary =
  | 'unit'
  | 'component'
  | 'full-app'
  | 'pglite'
  | 'http'
  | 'runtime'
  | 'migration'
  | 'electron'
  | 'package'
  | 'tooling'

export type TestProofClassification =
  | 'unique-behavior'
  | 'representative-boundary'
  | 'redundant-proof'
  | 'obsolete-contract'
  | 'implementation-coupled'
  | 'framework-only'

export type TestProofAuditEntry = {
  path: string
  boundary: TestProofBoundary
  classification: TestProofClassification
  proof: string
}

export type HighCostCaseAuditEntry = {
  path: string
  title: string
  maxDurationMs: number
  classification: TestProofClassification
  proof: string
}

